// Finds the selected actor-mask XZ bounding-box midpoint and writes midpoint Z plus 5000 when below
// the actorIndex actor Z, otherwise minus 5000, setting rotation 0x800 only in the first branch.
// Builds the matrix, calls BattleFx_SummonAlexanderClearCallbackRecords, schedules
// BattleFx_SummonAlexanderRunCallbackRecordsTask, chooses camera script
// g_BattleSummonAlexanderCameraScript1 or g_BattleSummonAlexanderCameraScript2 with rand,
// schedules BattleFx_SummonAlexanderTimelineTask and sets flag mask eight.
// Original native stack layout supplies midpoint Z through the third centroid output short into p;
// separately declared C locals do not guarantee this adjacency.
// FUNCTION: FF7 0x00501514
void __cdecl BattleFx_SummonBeginAlexander(int targetMask, int actorIdx)
{
    SVECTOR centroid;

    Battle_GetActorMaskCentroid(g_BattleSummonAlexanderTimer = targetMask, &centroid.vx);
    if (centroid.vz < g_BattleActorRecords[actorIdx].posZ) {
        ((BattleFxTimeDamageOrbitRing *)&g_BattleSummonAlexanderDword)->screenY = 2048;
        g_BattleSummonAlexanderBillboardMatrix.transZ = centroid.vz + 5000;
    } else {
        g_BattleSummonAlexanderBillboardMatrix.transZ = centroid.vz - 5000;
    }
    RotMatrix((SVECTOR *)&g_BattleSummonAlexanderDword, &(g_BattleSummonAlexanderBillboardMatrix.rotation));
    BattleFx_SummonAlexanderClearCallbackRecords();
    Battle_AllocateResourceSlot(BattleFx_SummonAlexanderRunCallbackRecordsTask);
    if ((rand() & 0x100) != 0) {
        BattleFx_AlexanderSpawnCameraScript(&g_BattleSummonAlexanderCameraScript1, &(g_BattleSummonAlexanderBillboardMatrix.rotation), actorIdx);
    } else {
        BattleFx_AlexanderSpawnCameraScript(&g_BattleSummonAlexanderCameraScript2, &(g_BattleSummonAlexanderBillboardMatrix.rotation), actorIdx);
    }
    Battle_AllocateResourceSlot(BattleFx_SummonAlexanderTimelineTask);
    g_BattleStageHideFlags |= 8;
}

