// Reads one short through the cursor pointer held at *cursorPtr and advances that cursor by two
// bytes. A negative value is used as a negated index into the short table at
// &g_BattleSummonAlexanderTable.operandTable and that entry is returned instead. Identical body to
// BattleFx_KjataReadCameraScriptOperand and BattleFx_FatChocoboReadCameraScriptOperand, which
// differ only in the table base.
// FUNCTION: FF7 0x00502546
short __cdecl BattleFx_AlexanderReadCameraScriptOperand(short **cursorPtr)
{
    int value;

    value = **cursorPtr;
    (*cursorPtr)++;
    if (value < 0) {
        value = (&g_BattleSummonAlexanderTable.operandTable)[-value];
    }
    return (short)value;
}

