// Camera shake for the Alexander summon, in three phases: the Y shake first, then the Z shake, then
// an ease-out of the Y shake. Frames 0 to 0x27 set the Y offset to 0x32, frames 0x28 to 0x45 set
// the Z amplitude to 0x32, and the last ten frames ease the Y offset down. On odd frames the
// offsets are added to the camera position and focal point, and on even frames they are subtracted,
// so the camera oscillates. After the last frame the task sets stage to 0xFFFF and returns. Nothing
// changes while the battle is paused.
// FUNCTION: FF7 0x005033f5
void __cdecl BattleFx_SummonAlexanderCameraYThenZShakeTask(void)
{
    int phaseFrame;
    int easeRatio;
    BattleFxPhaseControllerTask *task;

    task = (BattleFxPhaseControllerTask *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    g_BattleSummonAlexanderShakeAmplitude = 0;
    g_BattleSummonAlexanderShakeOffset = g_BattleSummonAlexanderShakeAmplitude;
    phaseFrame = task->frameCount;
    if (phaseFrame < 40) {
        g_BattleSummonAlexanderShakeOffset = 0x32;
    } else {
        phaseFrame -= 40;
        if (phaseFrame < 30) {
            g_BattleSummonAlexanderShakeAmplitude = 0x32;
        } else {
            phaseFrame -= 30;
            if (phaseFrame < 10) {
                easeRatio = (phaseFrame << 12) / 10;
                g_BattleSummonAlexanderShakeOffset = (0x1000 - easeRatio) * 0x32 >> 12;
            } else {
                task->stage = 0xFFFF;
                return;
            }
        }
    }
    if ((task->frameCount & 1) != 0) {
        g_BattleCameraPosition.cameraPosY += *(short *)&g_BattleSummonAlexanderShakeOffset;
        g_BattleCameraFocalPoint.focalPointY += *(short *)&g_BattleSummonAlexanderShakeOffset;
        g_BattleCameraPosZ += *(short *)&g_BattleSummonAlexanderShakeAmplitude;
        g_BattleCameraFocusZ += *(short *)&g_BattleSummonAlexanderShakeAmplitude;
    } else {
        g_BattleCameraPosition.cameraPosY -= *(short *)&g_BattleSummonAlexanderShakeOffset;
        g_BattleCameraFocalPoint.focalPointY -= *(short *)&g_BattleSummonAlexanderShakeOffset;
        g_BattleCameraPosZ -= *(short *)&g_BattleSummonAlexanderShakeAmplitude;
        g_BattleCameraFocusZ -= *(short *)&g_BattleSummonAlexanderShakeAmplitude;
    }
    (task->frameCount)++;
}

// Sets up g_BattleSummonAlexanderTransformMatrix: originX/originY from g_BattleViewportOriginX and
// g_BattleViewportOriginY, and scaleX/scaleY 0xC0/0x100 when g_BattleUiScalingMode == 2, else
// 0x60/0x80. Copies the billboard matrix's first element into billboardX and into the first element
// of the stage matrix (g_BattleSummonAlexanderMatrixSeam.stageMatrixHead), stores
// g_BattleSummonAlexanderBillboardMatrix.transZ (negated when the summon's Y rotation is zero) into
// translation[2], multiplies the camera matrix that ends the camera script by the stage matrix into
// a stack matrix with MultiplyMatrix, and passes that matrix and the transform's offscreen request to
// BattleFx_SummonAlexanderQueueStageOffscreenRequests.
// FUNCTION: FF7 0x00503576
void __cdecl BattleFx_SummonAlexanderBuildAndQueueStageOffscreenRequests(void)
{
    int m[8];

    if (g_BattleUiScalingMode == 2) {
        g_BattleSummonAlexanderTransformMatrix.originX = *(short *)&g_BattleViewportOriginX;
        g_BattleSummonAlexanderTransformMatrix.originY = *(short *)&g_BattleViewportOriginY;
        g_BattleSummonAlexanderTransformMatrix.scaleX = 0xC0;
        g_BattleSummonAlexanderTransformMatrix.scaleY = 0x100 /* 0.0625 */;
    } else {
        g_BattleSummonAlexanderTransformMatrix.originX = *(short *)&g_BattleViewportOriginX;
        g_BattleSummonAlexanderTransformMatrix.originY = *(short *)&g_BattleViewportOriginY;
        g_BattleSummonAlexanderTransformMatrix.scaleX = 0x60;
        g_BattleSummonAlexanderTransformMatrix.scaleY = 0x80;
    }
    g_BattleSummonAlexanderTransformMatrix.billboardX = *(short *)&(g_BattleSummonAlexanderBillboardMatrix.rotation);
    g_BattleSummonAlexanderMatrixSeam.stageMatrixHead[0] = g_BattleSummonAlexanderTransformMatrix.billboardX;
    if (((BattleFxTimeDamageOrbitRing *)&g_BattleSummonAlexanderDword)->screenY != 0) {
        g_BattleSummonAlexanderTransformMatrix.translation[2] = g_BattleSummonAlexanderBillboardMatrix.transZ;
    } else {
        g_BattleSummonAlexanderTransformMatrix.translation[2] = -g_BattleSummonAlexanderBillboardMatrix.transZ;
    }
    MultiplyMatrix(&g_BattleSummonAlexanderCameraScript2[304], g_BattleSummonAlexanderMatrixSeam.stageMatrixHead, m);
    BattleFx_SummonAlexanderQueueStageOffscreenRequests((int)m, (BattleFxOffscreenCaptureReq *)&g_BattleSummonAlexanderTransformMatrix.originX);
}

// Queues the offscreen render requests for one stage of the Alexander summon. The matrix argument
