            offscreenReq->viewportY = params->viewportY;
            offscreenReq->viewportW = params->viewportW;
            offscreenReq->viewportH = params->viewportH;
            offscreenReq->sampleStepX = 1;
            offscreenReq->sampleStepY = 1;
            g_BattleSummonAlexanderOffscreenSlot2 = offscreenReq->offscreenSlot;
