        ApplyDeferredDrawArgs();
        ptA = meshAddress + readPointer->offsetC;
        ptB = meshAddress + readPointer->nextOffsetB;
        vertC8 = meshAddress + readPointer->offsetD;
        Gfx_PsxStoreClearFlag(&calcCapFlags);
