// Spawns the swirling sprites of the Alexander summon while the battle is not paused. Each call
// claims a number of sprite records that depends on frameCount: one before frame 10, two until
// frame 40, four until frame 70, and six after that. Each record gets a random start position in
// one of three regions, a negative Y velocity, a negative X velocity and a random scale. The
// 0 test selects a fixed value in place of each random draw. Once frameCount reaches 140,
// the task sets stage to -1.
// FUNCTION: FF7 0x005047ca
void __cdecl BattleFx_SummonAlexanderSpawnSwirlingSpritesTask(void)
{
    int p, frameAmount;
    BattleFxPhaseControllerTask *taskPtr;
    int s, spawnIdx8, spawnCount;
    BattleFxAlexanderSprite *pSprite;

    taskPtr = (BattleFxPhaseControllerTask *)BATTLE_CURRENT_TASK_SLOT;
    if ((g_BattleFxSummonAlexanderSpawnSwirlingSpritesTaskInit & 1) == 0) {
        g_BattleFxSummonAlexanderSpawnSwirlingSpritesTaskInit |= 1;
        g_BattleSummonAlexanderActorIdx = Gfx_GetPsxScratchpadPtr(0);
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    frameAmount = taskPtr->frameCount;
    if (frameAmount < 10) {
        spawnCount = 1;
    } else {
        frameAmount -= 10;
        if (frameAmount < 30) {
            spawnCount = 2;
        } else {
            frameAmount -= 30;
            if (frameAmount < 30) {
                spawnCount = 4;
            } else {
                spawnCount = 6;
            }
        }
    }
    for (spawnIdx8 = 0; spawnIdx8 < spawnCount; spawnIdx8++) {
        pSprite = (BattleFxAlexanderSprite *)(BattleFx_SummonAlexanderClaimSpriteRecord((int)BattleFx_SummonAlexanderSwirlingSpriteRecordTask));
        pSprite->timer = 0;
        /* Uniform 3-way random branch (0..2). */
        switch (rand() % 3) {
        case 0:
            pSprite->posX = UNFOLDED(0) ? 6000 : rand() % 4000 + 2000;
            pSprite->posY = UNFOLDED(0) ? 6000 : rand() % 12000 - 6000;
            break;
        case 1:
            pSprite->posX = -(UNFOLDED(0) ? 6000 : rand() % 4000 + 2000);
            pSprite->posY = UNFOLDED(0) ? 6000 : rand() % 12000 - 6000;
            break;
        case 2:
            pSprite->posX = UNFOLDED(0) ? 6000 : rand() % 12000 - 6000;
            pSprite->posY = UNFOLDED(0) ? 6000 : rand() % 4000 + 2000;
        }
        pSprite->velocityY = -(UNFOLDED(0) ? 100 : rand() % 80 + 20);
        pSprite->velocityX = -(UNFOLDED(0) ? 64 : rand() % 64);
        pSprite->scale = UNFOLDED(0) ? 20480 : rand() % 14336 + 6144;
    }
    (taskPtr->frameCount)++;
    if (taskPtr->frameCount >= 140) {
        taskPtr->stage = -1;
    }
}

// Claims the first zero g_BattleSummonAlexanderVertexBuffer entry among 200 by storing tag, clears the first two words
// of its stride-24 g_BattleSummonAlexanderParticleBuffer record, and returns that record address; returns zero when full.
// FUNCTION: FF7 0x00504ab8
int __cdecl BattleFx_SummonAlexanderClaimSpriteRecord(int tag)
{
    int index;

    for (index = 0; index < 200; index++) {
        if (g_BattleSummonAlexanderVertexBuffer[index] == 0) {
            g_BattleSummonAlexanderVertexBuffer[index] = (void(__cdecl *)(int))tag;
            g_BattleSummonAlexanderParticleBuffer.records[index].state = 0;
            g_BattleSummonAlexanderParticleBuffer.records[index].word = 0;
            return (int)&g_BattleSummonAlexanderParticleBuffer.records[index];
        }
    }
    return 0;
}

// Per-frame task for one swirling sprite. It draws the sprite on every call, with its index as the
// frame and its scale. It advances the sprite only while the battle is not paused: the index is
// incremented, and once it exceeds g_BattleSummonAlexanderTargetActorIdx the record is retired by
// writing 0xFFFF into ownerSlot. Otherwise phase grows by phaseStep, and offsetX and offsetY are rotated
// by angle with SinFixed and CosFixed in 12-bit fixed point. The Z component (offsetY) uses the
// newly written X value (offsetX) rather than the previous one.
// FUNCTION: FF7 0x00504b24
void __cdecl BattleFx_SummonAlexanderSwirlingSpriteRecordTask(BattleFxSwirlingSprite *sprite)
{
    int sinAngle, cosine;

    BattleFx_SummonAlexanderDrawAnimatedSprite((char *)sprite + 4, sprite->index, sprite->scale);
    if (g_BattleIsPaused == 0) {
        (sprite->index)++;
        if (sprite->index > g_BattleSummonAlexanderTargetActorIdx) {
            sprite->ownerSlot = BATTLE_TASK_FREE;
        } else {
            sprite->phase += sprite->phaseStep;
            sinAngle = SinFixed(sprite->angle);
            cosine = CosFixed(sprite->angle);
            sprite->offsetX = (cosine * sprite->offsetX + sinAngle * sprite->offsetY) >> 12;
            sprite->offsetY = (-sinAngle * sprite->offsetX + cosine * sprite->offsetY) >> 12;
        }
    }
}

// Builds and submits one sprite draw. Resolves g_BattleSummonAlexanderPoseTable[10] and g_BattleSummonAlexanderPoseTable[11] from
// Gfx_ModelTableGetLoadedRecord(2, g_BattleSummonAlexanderTableCursor) and Gfx_ModelTableGetSpriteObject(2, g_BattleSummonAlexanderTableCursor), caches
// the animation's frame count (the second int of the record that entry points to) into g_BattleSummonAlexanderTargetActorIdx, positions the request
// with BattleFx_SummonAlexanderInstallSpriteMatrix(point, scale, 0), stores frameIndex into g_BattleSummonAlexanderSpriteRequest1.frameIndex, and appends it with
// BattleFx_SubmitSpriteDraw(&g_BattleSummonAlexanderPoseTable[10], g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead), keeping the
// returned list head in g_BattleOverlayDrawListHead.
// FUNCTION: FF7 0x00504c14
void __cdecl BattleFx_SummonAlexanderDrawAnimatedSprite(void *point, int frameIndex, int scale)
{
    g_BattleSummonAlexanderPoseTable[10] = Gfx_ModelTableGetLoadedRecord(2, g_BattleSummonAlexanderTableCursor);
    g_BattleSummonAlexanderPoseTable[11] = Gfx_ModelTableGetSpriteObject(2, g_BattleSummonAlexanderTableCursor);
    g_BattleSummonAlexanderTargetActorIdx = *(int *)((char *)*(int *)g_BattleSummonAlexanderPoseTable[10] + 4);
    BattleFx_SummonAlexanderInstallSpriteMatrix(point, (short)scale, 0);
    g_BattleSummonAlexanderSpriteRequest1.frameIndex = frameIndex;
    g_BattleOverlayDrawListHead = BattleFx_SubmitSpriteDraw(&g_BattleSummonAlexanderPoseTable[10], g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
}

// Copies value into g_BattleSummonAlexanderSpriteRecord.value, g_BattleSummonAlexanderSpriteScaleY
// and g_BattleSummonAlexanderQuad, installs g_BattleSummonAlexanderLightMatrix with
// SetRotMatrix/SetTransMatrix, rotates the point point into g_BattleSummonAlexanderSpriteRecord's
// x/y/z with RotTransPoint, and when distance is non-zero pushes that vector along its own
// normalised direction (NormalizeVectorFixed) by distance in 4.12 fixed point. Then installs
// g_BattleSummonAlexanderQuad as the matrix and returns its address.
