        sprite = (BattleFxAlexanderSprite *)(BattleFx_SummonAlexanderClaimSpriteRecord((int)BattleFx_SummonAlexanderYStepAnimatedSpriteRecordTask));
        theta = rand() & 0x7FF;
        sprite->posX = CosFixed(theta) * 0xBB8 >> 12;
