    if ((g_BattleFxSummonAlexanderGradientTriangleTaskInit & 1) == 0) {
        g_BattleFxSummonAlexanderGradientTriangleTaskInit |= 1;
        g_BattleSummonAlexanderTriangleState = Gfx_GetPsxScratchpadPtr(0);
    }
