    g_BattleSummonAlexanderStripQuad->stripLevel = taskSlot->corner0X;
    g_BattleSummonAlexanderStripQuad->corner2Y = 0;
    g_BattleSummonAlexanderStripQuad->corner0Y = 0;
    g_BattleSummonAlexanderStripQuad->corner3X = taskSlot->corner3X;
    g_BattleSummonAlexanderStripQuad->corner1X = g_BattleSummonAlexanderStripQuad->corner3X;
    g_BattleSummonAlexanderStripQuad->stripStart = taskSlot->corner1X - wOffset;
    g_BattleSummonAlexanderStripQuad->stripEnd = taskSlot->corner1X;
