// Per-frame handler for the current battle-effect slot (a 0x20-byte task record). Stores
// Gfx_ModelTableGetRenderObject(0, g_BattleSummonAlexanderTableCursor) in
// g_BattleSummonAlexanderModelDrawRequest.tableValue. Below frame 5 it zeroes the request's scale;
// from frame 5 on it retires the slot (stage 0xFFFF) and returns. The branch between them, which
// writes ((frame - 5) << 12) / 0 (a literal division by zero), needs frame - 5 < 0 and is never
// taken. Then computes w = (frame << 12) / 5 and r = (w * 0x5B00 >> 12) + 0x500, calls
// BattleFx_SummonAlexanderInstallSpriteMatrix(slot + 4, r, 0) and SetDrawColorRGB(0, 0, 0), submits
// the request's draw with BattleFx_SubmitModelDraw into the OT bucket
// g_BattleCurrentOrderingTable + BATTLE_OT_AFTER_SORTED_5 (shift 0, cursor g_BattleOverlayDrawListHead), and
// increments the frame counter unless g_BattleIsPaused is set.
// FUNCTION: FF7 0x00506d87
void __cdecl BattleFx_SummonAlexanderScalingModelTask(void)
{
    int scale, nextFrame;
    BattleFxPhaseControllerTask *rec;
    int frac;

    rec = (BattleFxPhaseControllerTask *)BATTLE_CURRENT_TASK_SLOT;
    g_BattleSummonAlexanderModelDrawRequest.tableValue = Gfx_ModelTableGetRenderObject(0, g_BattleSummonAlexanderTableCursor);
    nextFrame = rec->frameCount;
    if (nextFrame < 5) {
        g_BattleSummonAlexanderModelDrawRequest.scale = 0;
    } else {
        nextFrame -= 5;
        if (nextFrame < 0) {
            frac = (nextFrame << 12) / 0;
            g_BattleSummonAlexanderModelDrawRequest.scale = frac;
        } else {
            rec->stage = 0xFFFF;
            return;
        }
    }
    frac = (rec->frameCount << 12) / 5;
    scale = (frac * 0x5B00 /* 5.6875 */ >> 12) + 0x500;
    BattleFx_SummonAlexanderInstallSpriteMatrix((char *)rec + 4, scale, 0);
    SetDrawColorRGB(0, 0, 0);
    g_BattleOverlayDrawListHead = BattleFx_SubmitModelDraw((BattleFxModelDraw *)(((char *)&g_BattleSummonAlexanderModelDrawRequest + 0x8)), g_BattleCurrentOrderingTable + BATTLE_OT_AFTER_SORTED_5, 0, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        rec->frameCount += 1;
    }
}

// When unpaused allocates three BattleFx_SummonAlexanderScalingMeshTask slots with sector-derived random angles, radial XZ at
// radius 1000 shifted Z by 5000 and Y zero. Stores negative speed 512 through 767, angle, zero and
// scale 0x1000 through 0x1FFF; advances the parent counter and retires at three or above.
// Constant-false speed and scale branches are unused.
// FUNCTION: FF7 0x00506e9d
void __cdecl BattleFx_SummonAlexanderSpawnScalingMeshesTask(void)
{
    int angle;
    BattleTaskSlot *task;
    int meshIdx;
    BattleFxAlexanderScalingMesh *pMesh;
    int speedValue, bytesDraw;

    task = BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    for (meshIdx = 0; meshIdx < 3; meshIdx++) {
        pMesh = (BattleFxAlexanderScalingMesh *)BATTLE_NEW_TASK_SLOT(BattleFx_SummonAlexanderScalingMeshTask);
        angle = meshIdx * 0xE00 / 3 + rand() % 0x4AA + -0x100;
        pMesh->x = SinFixed(angle) * 0x3E8 >> 12;
        pMesh->y = 0;
        pMesh->z = (CosFixed(angle) * 0x3E8 >> 12) + 5000;
        if (DEAD_IN_RETAIL != 0) {
            speedValue = 768;
        } else {
            speedValue = rand() % 256 + 512;
        }
        pMesh->speed = -speedValue;
        pMesh->angle = angle;
        pMesh->rotZ = 0;
        if (DEAD_IN_RETAIL != 0) {
            bytesDraw = 0x2000;
        } else {
            bytesDraw = rand() % 4096 + 4096;
        }
        pMesh->scale = bytesDraw;
    }
    (task->frameCounter)++;
    if (task->frameCounter >= 3) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
}

// Per-frame task that scales and draws the mesh of Alexander's summon through the global animation
// config. The first call fetches a data block for the transform matrix and sets its scale fields to
// 0x1000. For the first five frames the scale grows as q->scale times frame/5 and scalingMeshParam
// is 0. For the next five frames the scale holds at q->scale and scalingMeshParam takes the same
// fraction. After ten frames the task sets ownerSlot to 0xFFFF and returns. Each frame the rotation
// comes from the mesh's speed, angle and rotZ members and the translation from x, y and z. The matrix is scaled, multiplied with the
