// Per-frame task for the Alexander shards. Its first call sets bit 1 of the table flag byte and
// loads the rotation record from Gfx_GetPsxScratchpadPtr(0). Frames 0 to 7 use flags 0x80 with scatter
// fraction 0 and the first pair of offscreen objects. Frames 8 to 13 use flags 0x88, a scatter
// fraction of (frame - 8) / 6 in 12-bit fixed point, and the second pair. From frame 14 it sets
// meshIndex to 0xFFFF and returns, which retires the slot. Unless the game is paused it advances
// the frame, moves posY by velocityY - 0x1E, decays velocityY by 0xD00 and adds 4, 8 and 0x15 to
// the angles.
// FUNCTION: FF7 0x0050749f
void __cdecl BattleFx_SummonAlexanderScatteredShardMeshTask(void)
{
    int localFrame;
    BattleFxAlexanderShardRecord *shardPtr;

    shardPtr = (BattleFxAlexanderShardRecord *)BATTLE_CURRENT_TASK_SLOT;
    if ((*(unsigned char *)&g_BattleSummonAlexanderTable.shardTaskInit & 1) == 0) {
        g_BattleSummonAlexanderTable.shardTaskInit |= 1;
        g_BattleSummonAlexanderScatterRotation = (BattleFxAlexanderShardScratch *)Gfx_GetPsxScratchpadPtr(0);
    }
    localFrame = shardPtr->frame;
    if (localFrame < 8) {
        g_BattleSummonAlexanderEffectDescriptor2.scatterMeshFlags = 0x80;
        g_BattleSummonAlexanderEffectDescriptor2.scatterFraction = 0;
        Gfx_SetPsxPrimQuadState(9, 4, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonAlexanderOffscreenSlot1));
        Gfx_SetPsxPrimQuadState(0xB, 4, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonAlexanderOffscreenSlot2));
    } else {
        localFrame -= 8;
        if (localFrame < 6) {
            g_BattleSummonAlexanderEffectDescriptor2.scatterMeshFlags = 0x88;
            g_BattleSummonAlexanderEffectDescriptor2.scatterFraction = (localFrame << 12) / 6;
            Gfx_SetPsxPrimQuadState(9, 1, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonAlexanderOffscreenSlot3));
            Gfx_SetPsxPrimQuadState(0xB, 1, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonAlexanderOffscreenSlot4));
        } else {
            shardPtr->meshIndex = 0xFFFF;
            return;
        }
    }
    g_BattleSummonAlexanderScatterRotation->angleX = shardPtr->angleX << 4;
    g_BattleSummonAlexanderScatterRotation->angleY = shardPtr->angleY << 4;
    g_BattleSummonAlexanderScatterRotation->angleZ = shardPtr->angleZ << 4;
    RotMatrixXYZ(g_BattleSummonAlexanderScatterRotation, &g_BattleSummonAlexanderScatterRotation->matrix);
    g_BattleSummonAlexanderScatterRotation->matrix.t[0] = shardPtr->posX;
    g_BattleSummonAlexanderScatterRotation->matrix.t[1] = shardPtr->posY;
    g_BattleSummonAlexanderScatterRotation->matrix.t[2] = shardPtr->posZ;
    g_BattleSummonAlexanderScatterRotation->scaleZ = shardPtr->rotation;
    g_BattleSummonAlexanderScatterRotation->scaleY = g_BattleSummonAlexanderScatterRotation->scaleZ;
    g_BattleSummonAlexanderScatterRotation->scaleX = g_BattleSummonAlexanderScatterRotation->scaleY;
    ScaleMatrix(&g_BattleSummonAlexanderScatterRotation->matrix, &g_BattleSummonAlexanderScatterRotation->scaleX);
    MultiplyMatrix(&g_BattleSummonAlexanderLightMatrix, &g_BattleSummonAlexanderScatterRotation->matrix, &g_BattleSummonAlexanderScatterRotation->matrix);
    SetRotMatrix(&g_BattleSummonAlexanderScatterRotation->matrix);
    SetTransMatrix(&g_BattleSummonAlexanderScatterRotation->matrix);
    g_BattleSummonAlexanderEffectDescriptor2.scatterMeshPtr = g_BattleSummonAlexanderResourceSubTable2Ptrs[shardPtr->meshIndex];
    SetDrawColorRGB(0, 0, 0);
    RefreshGlobalTransformState();
    g_BattleOverlayDrawListHead = BattleFx_AlexanderDrawPsxMesh((BattleFxProceduralMesh *)&g_BattleSummonAlexanderEffectDescriptor2.scatterMeshPtr, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        (shardPtr->frame)++;
        shardPtr->posY += (short)(shardPtr->velocityY - 30);
        shardPtr->velocityY = shardPtr->velocityY * 0xD00 /* 0.8125 */ >> 12;
        *(char *)&shardPtr->angleX += 4;
        *(char *)&shardPtr->angleY += 8;
        *(char *)&shardPtr->angleZ += 0x15;
    }
}

