// Per-frame task that eases actor record 3 for the Alexander summon. It does nothing while the game
// is paused. Before frame 0x1E it eases scale and tintPhase. From frame 0x1E to 0x27 it moves posZ
// by an eased step, adding it on odd frames and subtracting it on even ones; outside that range
// posZ is the billboard Z value. Below frame 0x28 posY follows a sine curve; for five frames after
// that it rises by 0xC8 each frame. Then it sets ownerSlot to 0xFFFF and returns without advancing
// the frame.
// FUNCTION: FF7 0x005078d8
void __cdecl BattleFx_SummonAlexanderEaseOffsetsTask(void)
{
    int localFrame;
    BattleTaskSlot *pTaskSlot;
    int iter, easedValue;

    pTaskSlot = BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (pTaskSlot->frameCounter >= 30 && pTaskSlot->frameCounter < 40) {
        localFrame = pTaskSlot->frameCounter - 30;
        easedValue = (localFrame << 12) / 10;
        if ((pTaskSlot->frameCounter & 1) != 0) {
            g_BattleActorRecords[3].posZ = g_BattleSummonAlexanderBillboardMatrix.transZ + (easedValue * 0x3E8 >> 12);
        } else {
            g_BattleActorRecords[3].posZ = g_BattleSummonAlexanderBillboardMatrix.transZ - (easedValue * 0x3E8 >> 12);
        }
    } else {
        g_BattleActorRecords[3].posZ = *(short *)&g_BattleSummonAlexanderBillboardMatrix.transZ;
    }
    if (pTaskSlot->frameCounter < 30) {
        easedValue = (pTaskSlot->frameCounter + 1 << 12) / 30;
        easedValue = 0x1000 - easedValue;
        for (iter = 0; iter < 2; iter++) {
            easedValue = SinFixed(easedValue / 4);
        }
        easedValue = 0x1000 - easedValue;
        g_BattleActorRecords[3].scale = (easedValue << 11 >> 12) + 0x800;
        g_BattleActorRecords[3].tintPhase = 0x1000 - easedValue;
    }
    localFrame = pTaskSlot->frameCounter;
    if (localFrame < 40) {
        easedValue = (localFrame + 1 << 12) / 40;
        easedValue = 0x1000 - easedValue;
        for (iter = 0; iter < 2; iter++) {
            easedValue = SinFixed(easedValue / 4);
        }
        easedValue = 0x1000 - easedValue;
        g_BattleActorRecords[3].posY = (easedValue * -21000 >> 12) + 20000;
    } else {
        localFrame -= 40;
        if (localFrame < 5) {
            g_BattleActorRecords[3].posY += 200;
        } else {
            pTaskSlot->ownerSlot = BATTLE_TASK_FREE;
            return;
        }
    }
    (pTaskSlot->frameCounter)++;
}

